.darma-loader-darma-b17-carpet-vacuum { --accent: var(--loader-color, #7c3aed); --accent-2: var(--loader-secondary-color, #a78bfa); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .66); position: relative; overflow: hidden; }
.darma-loader-darma-b17-carpet-vacuum .darma-loader-darma-b17-carpet-vacuum__dirty { position: absolute; left: 0; right: 0; bottom: 4%; height: 24%; border-radius: 4px; background: color-mix(in srgb, var(--accent) 18%, transparent); }
.darma-loader-darma-b17-carpet-vacuum .darma-loader-darma-b17-carpet-vacuum__clean { position: absolute; left: 0; bottom: 4%; height: 24%; width: 0; border-radius: 4px; background: repeating-linear-gradient(90deg, color-mix(in srgb, var(--accent-2) 60%, transparent) 0 8%, color-mix(in srgb, var(--accent-2) 30%, transparent) 0 16%); animation: darma-loader-darma-b17-carpet-vacuum-vac-clean calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b17-carpet-vacuum .darma-loader-darma-b17-carpet-vacuum__unit { position: absolute; left: 2%; bottom: 4%; width: 26%; height: 84%; animation: darma-loader-darma-b17-carpet-vacuum-vac-push calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b17-carpet-vacuum .darma-loader-darma-b17-carpet-vacuum__handle { position: absolute; left: 58%; top: 0; width: 14%; height: 76%; border-radius: 4px; background: linear-gradient(90deg, var(--accent-2), var(--accent)); transform: rotate(12deg); transform-origin: 50% 100%; }
.darma-loader-darma-b17-carpet-vacuum .darma-loader-darma-b17-carpet-vacuum__head { position: absolute; left: 0; bottom: 0; width: 100%; height: 26%; border-radius: 5px; background: linear-gradient(color-mix(in srgb, #fff 20%, var(--accent)), var(--accent)); }
.darma-loader-darma-b17-carpet-vacuum i { position: absolute; bottom: 26%; width: 6%; height: 6%; border-radius: 50%; background: color-mix(in srgb, var(--accent) 60%, transparent); opacity: 0; animation: darma-loader-darma-b17-carpet-vacuum-vac-dust calc(var(--loader-speed, 1s) * 1) ease-in infinite, darma-loader-darma-b17-carpet-vacuum-vac-push calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b17-carpet-vacuum i:nth-of-type(1) { left: 26%; }
.darma-loader-darma-b17-carpet-vacuum i:nth-of-type(2) { left: 32%; animation-delay: calc(var(--loader-speed, 1s) * .5), 0s; }
@keyframes darma-loader-darma-b17-carpet-vacuum-vac-push { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(calc(var(--loader-size, 128px) * .68)); } }
@keyframes darma-loader-darma-b17-carpet-vacuum-vac-clean { 0%, 100% { width: 4%; } 50% { width: 92%; } }
@keyframes darma-loader-darma-b17-carpet-vacuum-vac-dust { 0% { opacity: 0; transform: translate(0, 0) scale(.6); } 25% { opacity: .9; } 100% { opacity: 0; transform: translate(-90%, -50%) scale(1.2); } }

